begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(17);
select has_table('public','player_sessions','session telemetry exists');select has_column('public','properties','level_2_reached_at','level 2 timestamp exists');select has_column('public','properties','level_3_reached_at','level 3 timestamp exists');select has_function('public','get_admin_economy_dashboard_v2',array['integer'],'bounded dashboard exists');select has_function('public','admin_inspect_player',array['uuid'],'player inspection exists');select has_function('public','review_anomaly',array['bigint','text','text'],'anomaly review exists');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)values('00000000-0000-0000-0000-000000000000','77777777-7777-4777-8777-777777777777','authenticated','authenticated','alpha@example.test',crypt('password',gen_salt('bf')),now(),'{}','{"username":"AlphaTester"}',now(),now(),'','','','');
set local role authenticated;select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',true);select throws_like($$select public.get_admin_economy_dashboard_v2(1)$$,'%ADMIN_REQUIRED%','player dashboard denied');select throws_like($$select public.admin_inspect_player(auth.uid())$$,'%ADMIN_REQUIRED%','player inspection denied');select throws_like($$select public.review_anomaly(1,'REVIEWED',null)$$,'%ADMIN_REQUIRED%','review denied');select lives_ok($$select public.start_observed_session()$$,'session starts');select is((select count(*)from public.player_sessions where player_id=auth.uid()),1::bigint,'session persists');select lives_ok($$select public.heartbeat_observed_session((select id from public.player_sessions where player_id=auth.uid()))$$,'heartbeat updates');
reset role;update public.properties set level=2 where player_id='77777777-7777-4777-8777-777777777777';select isnt((select level_2_reached_at from public.properties where player_id='77777777-7777-4777-8777-777777777777'),null::timestamptz,'level 2 timestamp captured');update public.profiles set app_role='admin'where id='77777777-7777-4777-8777-777777777777';set local role authenticated;select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',true);select lives_ok($$select public.get_admin_economy_dashboard_v2(7)$$,'admin dashboard allowed');select lives_ok($$select public.admin_inspect_player(auth.uid())$$,'admin inspection allowed');select throws_like($$select public.get_admin_economy_dashboard_v2(365)$$,'%INVALID_PERIOD%','unbounded period rejected');select is((select count(*)from public.profiles where id<>auth.uid()),0::bigint,'cross-player profile remains hidden');select * from finish();rollback;
